#include <iostream>
#include <string>
#include <vector>

int main() {
    int val;
    std::cin >> val;
    std::string data;
    std::cin >> data;

    std::string tempData = data;
    std::string bracketsStr = "_";
    int startIndex = -1;
    int dataLength = static_cast<int>(tempData.length());

    for (int i = 0; i < dataLength; ++i) {
        char ch = tempData[i];
        if (ch == '(') {
            startIndex = i;
        } else if (ch == ')') {
            bracketsStr += tempData.substr(startIndex + 1, i - startIndex - 1) + "_";
            tempData = tempData.substr(0, startIndex) + "_" + tempData.substr(i + 1);
            dataLength = static_cast<int>(tempData.length());
            i = startIndex - 1;
            startIndex = -1;
        }
    }

    std::vector<std::string> bracketParts;
    size_t pos = 0;
    size_t found;
    while ((found = bracketsStr.find('_', pos)) != std::string::npos) {
        std::string part = bracketsStr.substr(pos, found - pos);
        if (!part.empty()) {
            bracketParts.push_back(part);
        }
        pos = found + 1;
    }
    // To include the last part if any
    if (pos < bracketsStr.size()) {
        std::string part = bracketsStr.substr(pos);
        if (!part.empty()) {
            bracketParts.push_back(part);
        }
    }

    int countBrackets = 0;
    for (const auto& part : bracketParts) {
        if (!part.empty()) {
            countBrackets++;
        }
    }

    std::vector<std::string> segmentsArray;
    pos = 0;
    while ((found = tempData.find('_', pos)) != std::string::npos) {
        segmentsArray.push_back(tempData.substr(pos, found - pos));
        pos = found + 1;
    }
    // To include the last segment if any
    if (pos < tempData.size()) {
        segmentsArray.push_back(tempData.substr(pos));
    }

    int maxSegment = 0;
    for (const auto& segment : segmentsArray) {
        if (static_cast<int>(segment.length()) > maxSegment) {
            maxSegment = segment.length();
        }
    }

    std::cout << maxSegment << " " << countBrackets << std::endl;

    return 0;
}
